/**
 * حركة وزيارات الآليات إلى المحطة التحويلية — سير العمل بالخطوات (00130):
 *  1) وصول الآلية ← تأكيد الوصول (مسؤول التطبيق في المحطة)
 *  2) كتابة الوزن (وقت الوزن تلقائي)
 *  3) اختيار الوجهة: مكبس أو محطة تحويلية + نوع الآلية (الأوزان المسموحة)
 *  4) الاكتمال: دفتر تلقائي + مخالفة إن قلّ الوزن + تنبيه غرفة العمليات
 * كل الأزمنة تُحسب وتظهر هنا وفي جدول غرفة العمليات.
 */
import { useMemo, useState, type ReactNode } from 'react'
import { useCanCall } from '@features/permissions/my-permissions'
import { AlertTriangle, ArrowLeftRight, CheckCircle2, Clock3, Filter, FolderOpen, MapPin, Scale, Search, Truck } from 'lucide-react'
import { useStationConfirmArrival, useStationDispatchVehicle, useStationMovementDays, useStationVisitsForDay } from '@features/vehicle-operations/hooks'
import { useCompleteWeighing, useRecordWeighing, useVehicleKinds, kindsForDestination, kindByKey, kindRangeLabel, weighingViolation, DESTINATION_LABELS, type WeighingDestination } from '@features/transfer-station'
import type { StationVisit } from '@sdk/vehicle-operations.sdk'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'

const dateTime = (value: string | null) => value ? new Intl.DateTimeFormat('ar-IQ-u-nu-latn', { dateStyle: 'short', timeStyle: 'short', timeZone: 'Asia/Baghdad' }).format(new Date(value)) : '—'
const minutes = (value: number | null) => value === null ? '—' : value < 60 ? `${value} د` : `${Math.floor(value / 60)} س ${value % 60} د`
const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Baghdad' }).format(new Date())
const statusLabel: Record<StationVisit['status'], string> = { in_transit: 'في الطريق', at_station: 'داخل المحطة', dispatched: 'غادرت المحطة' }
const statusTone: Record<StationVisit['status'], string> = { in_transit: 'bg-amber-100 text-amber-800', at_station: 'bg-orange-100 text-orange-800', dispatched: 'bg-emerald-100 text-emerald-800' }
type Action = 'arrive' | 'work_site' | 'garage' | 'weigh' | 'complete'

export default function StationVehicleMovementsPage() {
  const [selectedDay, setSelectedDay] = useState(today), [search, setSearch] = useState(''), [status, setStatus] = useState<'' | StationVisit['status']>(''), [sectorId, setSectorId] = useState('')
  const days = useStationMovementDays(), visits = useStationVisitsForDay(selectedDay, { search, status: status || undefined, sectorId: sectorId ? Number(sectorId) : undefined }), arrive = useStationConfirmArrival(), send = useStationDispatchVehicle()
  const canArrive = useCanCall('station_confirm_vehicle_arrival')
  const [target, setTarget] = useState<{ row: StationVisit; action: Action } | null>(null), [notes, setNotes] = useState('')
  const rows = useMemo(() => visits.data ?? [], [visits.data])
  const sectors = useMemo(() => [...new Map(rows.map(row => [row.sector_id, row.area_name])).entries()], [rows])
  const submit = () => {
    if (!target) return
    const done = () => { setTarget(null); setNotes('') }
    if (target.action === 'arrive') arrive.mutate({ legId: target.row.visit_id, notes: notes.trim() || undefined }, { onSuccess: done })
    else if (target.action === 'weigh' || target.action === 'complete') return // يُدار داخل الحوار
    else send.mutate({ departureId: target.row.departure_id, destination: target.action, notes: notes.trim() || undefined }, { onSuccess: done })
  }
  const open = rows.filter(row => row.status !== 'dispatched').length, totalStay = rows.reduce((sum, row) => sum + (row.stay_minutes ?? 0), 0)
  const actionTitle: Record<Action, string> = { arrive: 'تأكيد الوصول', work_site: 'العودة لموقع العمل', garage: 'الإرسال إلى الكراج', weigh: 'كتابة الوزن', complete: 'الوجهة وإكمال العملية' }
  return <section dir="rtl" className="space-y-5" data-testid="station-movements-page">
    <ExecPageHeader icon="truck" title="حركة وزيارات الآليات إلى المحطة" subtitle="سير عمل بالخطوات: وصول ← وزن ← وجهة ← اكتمال — كل زيارة مستقلة بوقت الوصول والوزن والوجهة ومدة البقاء، والبيانات كلها لغرفة العمليات."
      stats={[{ label: 'زيارات اليوم المختار', value: rows.length, tone: 'gold' }, { label: 'الحالات المفتوحة', value: open, tone: open ? 'red' : 'green' }, { label: 'إجمالي البقاء', value: minutes(totalStay) }]} />

    <div className="flex gap-3 overflow-x-auto pb-2">{(days.data ?? []).map(day => <button key={day.visit_day} data-testid={`station-day-${day.visit_day}`} onClick={() => setSelectedDay(day.visit_day)} className={`min-w-44 rounded-2xl border p-4 text-right transition ${selectedDay === day.visit_day ? 'border-[#0b3d6b] bg-[#0b3d6b]/5 shadow' : 'bg-white'}`}><span className="flex items-center gap-2 text-sm font-black"><FolderOpen size={17} className="text-[#0b3d6b]" />{new Intl.DateTimeFormat('ar-IQ-u-nu-latn', { dateStyle: 'medium', timeZone: 'Asia/Baghdad' }).format(new Date(`${day.visit_day}T12:00:00Z`))}</span><span className="mt-2 block text-[11px] text-slate-500">{day.visit_count} زيارة · {day.vehicle_count} رحلة</span><span className={`mt-1 block text-[11px] font-bold ${day.open_count ? 'text-amber-700' : 'text-emerald-700'}`}>{day.open_count ? `${day.open_count} حالة مفتوحة` : 'مكتمل'}</span></button>)}</div>


    <div className="grid gap-3 rounded-2xl border bg-white p-4 md:grid-cols-3"><label className="relative"><Search className="absolute right-3 top-3 text-slate-400" size={17} /><input aria-label="بحث الزيارات" value={search} onChange={e => setSearch(e.target.value)} className="h-11 w-full rounded-xl border pr-10 pl-3 text-sm" placeholder="DB أو الآلية أو السائق" /></label><label className="relative"><Filter className="absolute right-3 top-3 text-slate-400" size={17} /><select aria-label="فلتر الحالة" value={status} onChange={e => setStatus(e.target.value as '' | StationVisit['status'])} className="h-11 w-full rounded-xl border pr-10 pl-3 text-sm"><option value="">كل الحالات</option><option value="in_transit">في الطريق</option><option value="at_station">داخل المحطة</option><option value="dispatched">غادرت</option></select></label><select aria-label="فلتر المنطقة" value={sectorId} onChange={e => setSectorId(e.target.value)} className="h-11 w-full rounded-xl border px-3 text-sm"><option value="">كل المناطق</option>{sectors.map(([id, name]) => <option key={id} value={id}>{name}</option>)}</select></div>

    {visits.isLoading ? <p className="rounded-3xl border bg-white p-12 text-center text-sm text-slate-500">جارٍ تحميل سجل الزيارات…</p> : <div className="grid gap-4 lg:grid-cols-2">{rows.map(row => <VisitCard key={row.visit_id} row={row} onAction={action => { setTarget({ row, action }); setNotes('') }} />)}</div>}
    {!visits.isLoading && !rows.length && <p className="rounded-3xl border bg-white p-12 text-center text-sm text-slate-500">لا توجد زيارات مطابقة في اليوم المختار.</p>}

    {target && (target.action === 'weigh' || target.action === 'complete'
      ? <WeighingDialog row={target.row} step={target.action} onClose={() => setTarget(null)} />
      : <div className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-slate-950/60 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-md rounded-3xl bg-white p-6"><h2 className="text-lg font-black">تأكيد حركة الآلية DB {target.row.db_number}</h2><p className="mt-2 text-xs text-slate-500">الزيارة رقم {target.row.visit_number} · {actionTitle[target.action]}</p><textarea data-testid="station-action-notes" value={notes} onChange={e => setNotes(e.target.value)} rows={3} maxLength={1000} className="mt-4 w-full rounded-xl border p-3" placeholder="ملاحظات اختيارية" /><div className="mt-4 grid grid-cols-2 gap-2"><button onClick={() => setTarget(null)} className="h-11 rounded-xl border">إلغاء</button><button data-testid="confirm-station-action" onClick={submit} disabled={arrive.isPending || send.isPending || (target.action === 'arrive' && !canArrive.allowed)} title={target.action === 'arrive' ? canArrive.title : undefined} className="flex h-11 items-center justify-center gap-2 rounded-xl bg-orange-700 font-black text-white disabled:opacity-40"><CheckCircle2 size={16} />تأكيد وإبلاغ</button></div></div></div>)}
  </section>
}

/** حوار خطوتي الوزن والوجهة — الأوزان المسموحة والمخالفة الفورية */
function WeighingDialog({ row, step, onClose }: { row: StationVisit; step: 'weigh' | 'complete'; onClose: () => void }) {
  const record = useRecordWeighing(), complete = useCompleteWeighing()
  const { kinds: allKinds } = useVehicleKinds()
  const [weight, setWeight] = useState(row.step_weight_tons?.toString() ?? '')
  const [destination, setDestination] = useState<WeighingDestination>('press')
  const [kind, setKind] = useState('compactor_medium')
  const weightValue = Number(weight)
  const hasWeight = weight.trim() !== '' && Number.isFinite(weightValue) && weightValue > 0
  const preview = weighingViolation(kind, hasWeight ? weightValue : null, allKinds)
  const kinds = kindsForDestination(destination, allKinds)
  const submitWeigh = () => { if (!hasWeight) return; record.mutate({ visitLegId: row.visit_id, weightTons: +weightValue.toFixed(2) }, { onSuccess: onClose }) }
  const submitComplete = () => complete.mutate({ visitLegId: row.visit_id, destination, vehicleKind: kind }, { onSuccess: onClose })
  return <div className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-slate-950/60 p-4" role="dialog" aria-modal="true" data-testid="weighing-dialog">
    <div className="w-full max-w-lg rounded-3xl bg-white p-6">
      <h2 className="flex items-center gap-2 text-lg font-black"><Scale size={18} className="text-[#0b3d6b]" />{step === 'weigh' ? 'كتابة الوزن' : 'الوجهة وإكمال العملية'} — DB {row.db_number}</h2>
      <p className="mt-1 text-xs text-slate-500">{row.vehicle_name} · {row.driver_name} · وصل {dateTime(row.arrived_at)}</p>
      {step === 'weigh' ? <>
        <label className="mt-4 block text-xs font-black text-slate-600">الوزن الصافي (طن)<input data-testid="weighing-weight" type="number" min={0.1} max={99} step={0.1} value={weight} onChange={e => setWeight(e.target.value)} className="mt-1 h-11 w-full rounded-xl border px-3 text-sm font-bold" placeholder="مثال: 5.5" /></label>
        <p className="mt-2 text-[11px] text-slate-500">يُختم وقت الوزن تلقائياً لحظة الحفظ، وتُختار الوجهة في الخطوة التالية.</p>
        <div className="mt-4 grid grid-cols-2 gap-2"><button onClick={onClose} className="h-11 rounded-xl border">إلغاء</button><button data-testid="confirm-weighing" onClick={submitWeigh} disabled={!hasWeight || record.isPending} className="h-11 rounded-xl bg-orange-700 font-black text-white disabled:opacity-40">حفظ الوزن</button></div>
      </> : <>
        <p className="mt-3 rounded-xl bg-slate-50 p-3 text-xs font-bold text-slate-700">الوزن المسجل: {row.step_weight_tons} طن · وقت الوزن {dateTime(row.step_weighed_at ?? null)}</p>
        <fieldset className="mt-4"><legend className="text-xs font-black text-slate-600">الوجهة</legend><div className="mt-2 grid grid-cols-2 gap-2">{(Object.keys(DESTINATION_LABELS) as WeighingDestination[]).map(dest => <label key={dest} className={`flex cursor-pointer items-center justify-center gap-2 rounded-xl border p-3 text-sm font-black ${destination === dest ? 'border-orange-600 bg-orange-50 text-orange-800' : 'text-slate-600'}`}><input type="radio" name="weighing-destination" data-testid={`weighing-dest-${dest}`} checked={destination === dest} onChange={() => { setDestination(dest); if (!kindsForDestination(dest, allKinds).some(entry => entry.kind === kind)) setKind(kindsForDestination(dest, allKinds)[0]?.kind ?? 'compactor_small') }} className="sr-only" />{DESTINATION_LABELS[dest]}</label>)}</div></fieldset>
        <label className="mt-4 block text-xs font-black text-slate-600">نوع الآلية<select data-testid="weighing-kind" value={kind} onChange={e => setKind(e.target.value)} className="mt-1 h-11 w-full rounded-xl border px-3 text-sm font-bold">{kinds.map(entry => <option key={entry.kind} value={entry.kind}>{entry.label} — {kindRangeLabel(entry)}</option>)}</select></label>
        <p className="mt-1 text-[10px] text-slate-400">حدود الأوزان تُدار من غرفة العمليات وتُطبَّق هنا تلقائياً.</p>
        {preview.violates && <p data-testid="weighing-violation-warning" className="mt-3 flex items-center gap-2 rounded-xl bg-red-50 p-3 text-xs font-black text-red-700"><AlertTriangle size={15} />وزن أقل من الحد المسموح ({preview.minTons} طن) — سيُسجل مخالفة على السائق وتنبيه لغرفة العمليات (فرق {preview.deficit} طن).</p>}
        {!preview.violates && <p className="mt-3 rounded-xl bg-emerald-50 p-3 text-xs font-bold text-emerald-700">الوزن ضمن المسموح — عند الإكمال يُحفظ السجل ويُرسل لغرفة العمليات.</p>}
        <div className="mt-4 grid grid-cols-2 gap-2"><button onClick={onClose} className="h-11 rounded-xl border">إلغاء</button><button data-testid="confirm-complete" onClick={submitComplete} disabled={complete.isPending} className="h-11 rounded-xl bg-emerald-700 font-black text-white disabled:opacity-40">إكمال العملية</button></div>
      </>}
      {(record.error || complete.error) && <p className="mt-3 rounded-xl bg-red-50 p-3 text-xs font-black text-red-700">{(record.error as Error | null)?.message ?? (complete.error as Error | null)?.message}</p>}
    </div>
  </div>
}

function VisitCard({ row, onAction }: { row: StationVisit; onAction: (action: Action) => void }) {
  const weighed = row.step_weight_tons !== null && row.step_weight_tons !== undefined
  const completed = Boolean(row.step_completed_at)
  const { kinds: allKinds } = useVehicleKinds()
  const kindLabel = row.step_vehicle_kind ? kindByKey(row.step_vehicle_kind, allKinds)?.label ?? row.step_vehicle_kind : null
  return <article className="rounded-3xl border bg-white p-5 shadow-sm" data-testid={`station-visit-${row.visit_id}`}>
    <div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><b className="rounded-lg bg-slate-900 px-2 py-1 text-xs text-white">DB {row.db_number}</b><span className={`rounded-full px-2 py-1 text-[10px] font-black ${statusTone[row.status]}`}>{statusLabel[row.status]}</span><span className="text-[10px] font-bold text-slate-400">الزيارة #{row.visit_number}</span>{row.step_violation && <span className="flex items-center gap-1 rounded-full bg-red-100 px-2 py-1 text-[10px] font-black text-red-700"><AlertTriangle size={11} />مخالفة وزن</span>}</div><h2 className="mt-3 font-black">{row.vehicle_name}</h2><p className="mt-1 text-xs text-slate-500">{row.driver_name} · {row.shift}</p></div><ArrowLeftRight className="text-[#0b3d6b]" /></div>
    <div className="mt-4 grid grid-cols-2 gap-2 text-xs"><Info label="منطقة العمل" value={row.area_name} icon={<MapPin />} /><Info label="مسؤول القسم" value={row.manager_name} icon={<Truck />} /><Info label="غادرت للمحطة" value={dateTime(row.inbound_departed_at)} icon={<Clock3 />} /><Info label="وصلت المحطة" value={dateTime(row.arrived_at)} icon={<CheckCircle2 />} /><Info label="مدة الطريق" value={minutes(row.transit_minutes)} icon={<Clock3 />} /><Info label="مدة البقاء" value={minutes(row.stay_minutes)} icon={<Clock3 />} /></div>
    {completed && <div className="mt-3 rounded-2xl bg-emerald-50 p-3 text-xs font-bold text-emerald-800" data-testid={`weighing-summary-${row.visit_id}`}>اكتملت العملية: الوزن {row.step_weight_tons} طن · الوجهة {row.step_destination === 'press' ? 'المكبس' : 'المحطة التحويلية'} · {kindLabel} · الوزن {dateTime(row.step_weighed_at ?? null)} · الاكتمال {dateTime(row.step_completed_at ?? null)}.{row.step_corrected_at ? <span className="mr-1 rounded-md bg-amber-100 px-1.5 py-0.5 text-[10px] text-amber-800" data-testid={`weighing-corrected-${row.visit_id}`}>صُحح من غرفة العمليات</span> : null}</div>}
    {weighed && !completed && <p className="mt-3 rounded-2xl bg-amber-50 p-3 text-xs font-bold text-amber-800">الوزن المسجل {row.step_weight_tons} طن — بانتظار اختيار الوجهة وإكمال العملية.</p>}
    <Notes row={row} />
    {row.status === 'in_transit' && <button data-testid={`station-arrive-${row.visit_id}`} onClick={() => onAction('arrive')} className="mt-4 h-11 w-full rounded-xl bg-emerald-700 font-black text-white">تأكيد وصول الآلية إلى المحطة</button>}
    {row.status === 'at_station' && !weighed && <button data-testid={`station-weigh-${row.visit_id}`} onClick={() => onAction('weigh')} className="mt-4 flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-orange-700 font-black text-white"><Scale size={16} />كتابة الوزن</button>}
    {row.status === 'at_station' && weighed && !completed && <button data-testid={`station-complete-${row.visit_id}`} onClick={() => onAction('complete')} className="mt-4 flex h-11 w-full items-center justify-center gap-2 rounded-xl bg-emerald-700 font-black text-white"><CheckCircle2 size={16} />الوجهة وإكمال العملية</button>}
    {row.status === 'at_station' && completed && <div className="mt-4 grid grid-cols-2 gap-2"><button data-testid={`station-work-${row.visit_id}`} onClick={() => onAction('work_site')} className="h-11 rounded-xl bg-cyan-700 text-xs font-black text-white">عودة إلى موقع العمل</button><button data-testid={`station-garage-${row.visit_id}`} onClick={() => onAction('garage')} className="h-11 rounded-xl bg-slate-800 text-xs font-black text-white">إرسال إلى الكراج</button></div>}
    {row.dispatched_at && <p className="mt-3 rounded-xl bg-emerald-50 p-3 text-xs text-emerald-800">غادرت {dateTime(row.dispatched_at)} إلى {row.outbound_destination === 'garage' ? 'الكراج' : 'موقع العمل'}.</p>}
  </article>
}
function Notes({ row }: { row: StationVisit }) { const notes = [['الإرسال', row.inbound_notes], ['الوصول', row.arrival_notes], ['المغادرة', row.dispatch_notes]].filter(([, value]) => value); return notes.length ? <div className="mt-3 space-y-1 rounded-xl bg-slate-50 p-3 text-[11px] text-slate-600">{notes.map(([label, value]) => <p key={label}><b>{label}:</b> {value}</p>)}</div> : null }
function Info({ label, value, icon }: { label: string; value: string; icon: ReactNode }) { return <div className="rounded-xl bg-slate-50 p-3"><span className="flex items-center gap-1 text-[10px] text-slate-400">{icon}{label}</span><b className="mt-1 block">{value}</b></div> }
